on conflict (municipality_id,indicator_code,reference_year,reference_period,source_id) do update set
 indicator_name=excluded.indicator_name,value=excluded.value,unit=excluded.unit,source_url=excluded.source_url,
 retrieved_at=now(),verification_status=excluded.verification_status,notes=excluded.notes,
 geographic_level=excluded.geographic_level,geographic_name=excluded.geographic_name,updated_at=now();

update public.data_sources set
 description='Муниципальный паспорт Сургута: общая занятость и занятость по 16 отраслям, отгрузка собственной продукции, перепродажа товаров и численность зарегистрированных организаций. Есть Q1, H1, Q3 и годовые значения за 2024–2026 годы в зависимости от показателя.',
 coverage='Сургут · 191 наблюдение: общий уровень и 16 отраслей; периоды Q1, H1, Q3 и годовые итоги, 2024–2026 годы',
 notes='Значения Q1, H1, Q3 и annual являются отдельными периодными оценками; их нельзя складывать. Занятость — среднесписочная численность за соответствующий период, без субъектов малого предпринимательства. Отгрузка и перепродажа — накопительные денежные итоги с начала года.',
 import_status='partially_imported',last_checked_at=now(),updated_at=now()
where id='rosstat_surgut_passport_economy_2024_2026';